diff --git a/test/conformance/serial/ptp.go b/test/conformance/serial/ptp.go
index a528935c..ffb6ab6f 100644
--- a/test/conformance/serial/ptp.go
+++ b/test/conformance/serial/ptp.go
@@ -2117,6 +2117,17 @@ var _ = Describe("["+strings.ToLower(DesiredMode.String())+"-serial]", Serial, f
 					)
 				})

+				// Test framework BC configs use gmCapable=0, but real deployments default to
+				// gmCapable=1. Without it, ptp4l won't report clock class degradation on sync loss.
+				ptpConfigName := fullConfig.DiscoveredClockUnderTestPtpConfig.Name
+				originalConf := ptptesthelper.EnableGMCapableInPlace(ptpConfigName)
+				DeferCleanup(func() {
+					ptptesthelper.RestorePtp4lConf(ptpConfigName, originalConf)
+				})
+				configFile, err := ptptesthelper.DiscoverPtp4lConfigByProfile(ptpConfigName, slavePodNodeName)
+				Expect(err).NotTo(HaveOccurred())
+				ptptesthelper.WaitForConfigContent(fullConfig, configFile, "gmCapable 1")
+
 				By("Checking initial clock class is Locked (6)")
 				checkClockClassState(fullConfig, strconv.Itoa(int(fbprotocol.ClockClass6)), pkg.TimeoutIn5Minutes)

@@ -3514,6 +3525,20 @@ func waitForClockClass(fullConfig testconfig.TestConfig, expectedState string) {
 }

 func checkClockClassStateReturnBool(fullConfig testconfig.TestConfig, expectedState string) bool {
+	if !ptphelper.IsPTPOperatorVersionAtLeast("4.18") {
+		expected, err := strconv.Atoi(expectedState)
+		if err != nil {
+			return false
+		}
+		cc, err := ptptesthelper.GetClockClassForClockUnderTest(fullConfig)
+		if err != nil {
+			fmt.Fprintf(GinkgoWriter, "PMC clock class check error: %v\n", err)
+			return false
+		}
+		fmt.Fprintf(GinkgoWriter, "PMC clock class: %d (expected %d)\n", cc, expected)
+		return cc == expected
+	}
+
 	buf, _, err := pods.ExecCommand(client.Client, true, fullConfig.DiscoveredClockUnderTestPod, pkg.PtpContainerName, []string{"curl", pkg.MetricsEndPoint})
 	if err != nil {
 		refreshPodOnNotFound(fullConfig.DiscoveredClockUnderTestPod, err)
diff --git a/test/pkg/ptptesthelper/ptptesthelper.go b/test/pkg/ptptesthelper/ptptesthelper.go
index a0d28183..93089693 100644
--- a/test/pkg/ptptesthelper/ptptesthelper.go
+++ b/test/pkg/ptptesthelper/ptptesthelper.go
@@ -439,6 +439,7 @@ func (p *PortEngine) TurnAllPortsDown(skippedInterfaces map[string]bool) error {
 			logrus.Infof("Skipping interface: %s (in skip list)", port)
 			continue
 		}
+		p.nmSetManaged(port, false)
 		stdout, stderr, err := pods.ExecCommand(client.Client, true, p.ClockPod, pkg.RecoveryNetworkOutageDaemonSetContainerName,
 			[]string{"ip", "link", "set", port, "down"})
 		if err != nil {
@@ -461,6 +462,7 @@ func (p *PortEngine) TurnAllPortsUp() error {
 		if err != nil {
 			return err
 		}
+		p.nmSetManaged(port, true)

 		logrus.Infof("Turning interface: %s in pod %s up, stdout: %s, stderr: %s", port, p.ClockPod.Name, stdout.String(), stderr.String())
 	}
@@ -755,17 +757,31 @@ func verifyNodeClockClassWithMetrics(fullConfig testconfig.TestConfig, expectedC
 		fmt.Sprintf("Expected node-level clock class metric %d", expectedClass))
 }

+// GetClockClassForClockUnderTest reads the grandmaster clock class via PMC for the
+// discovered clock-under-test PtpConfig.
+func GetClockClassForClockUnderTest(fullConfig testconfig.TestConfig) (int, error) {
+	if fullConfig.DiscoveredClockUnderTestPod == nil || fullConfig.DiscoveredClockUnderTestPtpConfig == nil {
+		return -1, fmt.Errorf("clock under test not discovered")
+	}
+	configFile, err := DiscoverPtp4lConfigByProfile(
+		fullConfig.DiscoveredClockUnderTestPtpConfig.Name,
+		fullConfig.DiscoveredClockUnderTestPod.Spec.NodeName)
+	if err != nil {
+		return -1, err
+	}
+	return GetClockClassViaPMC(fullConfig, configFile)
+}
+
 // VerifyNICClockClass checks the expected clock class for a NIC via PMC and metrics.
 // isDualNIC controls the metric check on OCP < 4.18:
-//   - On OCP >= 4.18: always verifies via per-config metric (config label available).
-//   - On OCP < 4.18, single NIC: verifie

